package org.kanger;
import java.util.*;import java.lang.reflect.*;
import org.kanger.ContextProductionNativeBinding.Entry;
import org.kanger.ContextProductionNativeBinding.Snapshot;
import org.kanger.ContextSignedUnaryModel.*;
import org.kanger.ContextWitnessResultTransport.Cut;
final class ContextMultivariableModelMatrix {
 static int checks;static final int WORK=64000000;static final String RULE="!@u @v p(u)&&q(v)->r(u);";
 static void require(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}
 static Snapshot bind(boolean x,String t)throws Exception{return ContextSignedUnaryModelMatrix.bind(x,t);}
 static Interpretation model(Object... truth)throws Exception{return ContextSignedUnaryModelMatrix.m(ContextSignedUnaryModelMatrix.one(),Collections.emptyMap(),truth);}
 static Map<Cut,Interpretation> models(Snapshot x,Interpretation m){return ContextSignedUnaryModelMatrix.models(x,m);}
 static Result original(Snapshot x,Interpretation m){return ContextSignedUnaryModel.run(x,Collections.emptyList(),models(x,m),ContextSignedUnaryModelMatrix.policy());}
 static void reject(ReflectiveOperation a,String why)throws Exception{boolean no=false;try{a.run();}catch(InvocationTargetException ex){if(!(ex.getCause() instanceof IllegalStateException))throw ex;no=true;}require(no,why);}
 interface ReflectiveOperation{void run()throws Exception;}
 static void original()throws Exception{
  Snapshot x=bind(true,"!@u @v p(u)||q(v);");int accepted=0,diagonalOnly=0;
  for(int mask=0;mask<16;mask++){boolean[] p={(mask&1)!=0,(mask&2)!=0},q={(mask&4)!=0,(mask&8)!=0};boolean expected=true,diagonal=true;for(int u=0;u<2;u++){diagonal&=p[u]||q[u];for(int v=0;v<2;v++)expected&=p[u]||q[v];}Result r=original(x,model("p",p,"q",q));require((r.output!=null)==expected,"Cartesian truth oracle mask="+mask+" "+r.reason);if(r.output!=null){accepted++;ContextSignedUnaryModelAudit.check(r.output,x,Collections.emptyList(),r.output.ledger.models,r.output.ledger.policy,WORK);}if(diagonal&&!expected){diagonalOnly++;require(r.reason.contains("Cartesian"),"off-diagonal failure must be logical evaluation, not unsupported shape");}}
  require(accepted==7&&diagonalOnly==2,"exhaustive 16 interpretations separate Cartesian/diagonal semantics including outside class");
  Snapshot same=bind(true,"!@u p(u)||q(u);");require(original(same,model("p",new boolean[]{true,false},"q",new boolean[]{false,true})).output!=null,"same variable remains correlated, unlike independent u/v");
  Interpretation namedCross=new Interpretation(Arrays.asList(ContextSignedUnaryModelMatrix.one(),ContextSignedEligibilityMatrix.value(2)),ContextSignedUnaryModelMatrix.truth("p",new boolean[]{true,false,true},"q",new boolean[]{false,true,true}),Collections.emptyMap());require(original(x,namedCross).output==null,"off-diagonal different NAMED values also checked");
  Snapshot three=bind(true,"!@u @v @w p(u)||q(v)||r(w);");require(original(three,model("p",new boolean[]{true,true},"q",new boolean[]{false,false},"r",new boolean[]{false,false})).output!=null,"three independent universally quantified variables supported");
  User user=new User();Mind mind=new Mind(user);user.setCurrentMind(mind);require(mind.compile("!@u @v @w @z p(u)||q(v)||r(w)||s(z);",null,false),"actual four-variable syntax compiles");ContextProductionInventory inventory=ContextProductionInventory.inspect(mind,UUID.randomUUID(),1,true,Collections.emptyList(),1000);ContextProductionNativeBinding.Result four=ContextProductionNativeBinding.bind(mind,inventory,WORK,500000);require(!four.bound&&four.snapshot==null&&four.reason.contains("variable limit"),"existing native binding four-variable boundary unchanged, no partial snapshot");
  Snapshot sparse=bind(true,"!@u @v @w p(u)&&(q(v)||r(w));");require(original(sparse,model("p",new boolean[]{true,true},"q",new boolean[]{true,true},"r",new boolean[]{false,false})).output!=null,"whole multi-clause row with independent variable identities");
  Interpretation good=model("p",new boolean[]{true,true},"q",new boolean[]{false,false});Result ok=original(x,good);require(ok.output!=null,"valid interpretation");
  boolean bounded=false;try{ContextSignedUnaryModelAudit.check(ok.output,x,Collections.emptyList(),ok.output.ledger.models,ok.output.ledger.policy,1);}catch(IllegalStateException ex){bounded=true;}require(bounded,"Cartesian audit work limit fails closed");
  System.out.println("MULTIVARIABLE_ORIGINAL exhaustiveInterpretations=16 valid=7 diagonalOnlyRejected=2 allOtherCrossPositions=true threeVariables=true");
 }
 static ContextSignedWitnessNativeBranch.Receipt branch(Snapshot x,List<Snapshot> fs,boolean no){ContextSignedWitnessNativeBranch.Policy p=ContextSignedWitnessNativeMatrix.policy();ContextSignedWitnessNativeBranch.Result r=ContextSignedWitnessNativeBranch.run(x,fs,p);require(r.status==(no?ContextSignedWitnessNativeBranch.Status.REFUTED:ContextSignedWitnessNativeBranch.Status.QUIESCENT_SUPPLIED),r.phase+": "+r.reason);return no?r.rejection:r.output;}
 static void finalAudit()throws Exception{
  Snapshot x=bind(true,RULE);ContextSignedWitnessNativeBranch.Receipt b=branch(x,Collections.emptyList(),false);Interpretation good=model("p",new boolean[]{false,false},"q",new boolean[]{false,false},"r",new boolean[]{false,false});Result initial=original(x,good);require(initial.output!=null,initial.reason);
  Map<Cut,ContextSignedUnaryBranchModel.Extension> extensions=Collections.singletonMap(Cut.of(x),new ContextSignedUnaryBranchModel.Extension(Collections.emptyMap(),Collections.emptyMap()));ContextSignedUnaryBranchModel.Result result=ContextSignedUnaryBranchModel.run(initial.output,b,extensions,ContextSignedUnaryBranchMatrix.policy());require(result.output!=null,result.reason);
  ContextSignedUnaryBranchModelAudit.check(result.output,initial.output,b,extensions,result.output.ledger.policy,WORK);require(true,"fresh independent all-final audit");
  ContextSignedUnaryBranchModel.Obligation actual=null;for(ContextSignedUnaryBranchModel.Obligation o:result.output.ledger.obligations)if(o.kind==ContextSignedUnaryBranchModel.Kind.TERMINAL&&((ContextUniversalFrozenConstraints.Proof)o.carrier).clause.variables.size()==2){actual=o;break;}require(actual!=null,"actual two-variable final carrier, not synthetic clause");
  Method evaluate=ContextSignedUnaryBranchModelAudit.class.getDeclaredMethod("evaluate",ContextSignedUnaryBranchModel.Obligation.class,Interpretation.class,ContextSignedUnaryBranchModel.Extension.class,Runnable.class);evaluate.setAccessible(true);final ContextSignedUnaryBranchModel.Obligation obligation=actual;
  // ~p(u)||~q(v)||r(u) is true on both diagonal positions, but FALSE at u=outside,v=named.
  Interpretation diagonal=model("p",new boolean[]{false,true},"q",new boolean[]{true,false},"r",new boolean[]{false,false});require(!diagonal.truth.get("p").get(0)||!diagonal.truth.get("q").get(0),"named diagonal true");require(!diagonal.truth.get("p").get(1)||!diagonal.truth.get("q").get(1),"outside diagonal true");
  reject(()->evaluate.invoke(null,obligation,diagonal,extensions.get(Cut.of(x)),(Runnable)()->{}),"final evaluator rejects off-diagonal ALL-other/named pair");
  reject(()->evaluate.invoke(null,obligation,good,extensions.get(Cut.of(x)),ContextGroundProductionRounds.budget(1)),"final Cartesian enumeration obeys work budget");
  ContextSignedModelInspection.Result automatic=ContextSignedModelInspection.inspectAutomatic(x,Collections.emptyList(),new ContextSignedModelRequest("!p(1);",Collections.emptyMap()).policy);require(automatic.status==ContextSignedModelInspection.Status.MODELLED_SUPPLIED,automatic.reason);
  Snapshot unsupported=bind(true,"!@u @v p(u)||q(v);");require(ContextSignedModelInspection.inspectAutomatic(unsupported,Collections.emptyList(),new ContextSignedModelRequest("!p(1);",Collections.emptyMap()).policy).status==ContextSignedModelInspection.Status.INCOMPLETE,"native profile still refuses unsupported positive multivariable disjunction");
  System.out.println("MULTIVARIABLE_FINAL actualCarrier=true independentCartesianAudit=true outsideNamedPair=true searchIntegrated=true nativeProfileNotWeakened=true");
 }
 static void topology()throws Exception{
  Snapshot x=bind(true,RULE),a=bind(false,"!p(1);"),b=bind(false,"!~p(1);");for(boolean reverse:new boolean[]{false,true}){List<Snapshot> fs=reverse?Arrays.asList(b,a):Arrays.asList(a,b);ContextSignedWitnessNativeBranch.Receipt branch=branch(x,fs,false);Map<Cut,Interpretation> ms=ContextSignedUnaryModelMatrix.models(x,model("p",new boolean[]{false,false},"q",new boolean[]{false,false},"r",new boolean[]{false,false}),a,model("p",new boolean[]{true,false},"q",new boolean[]{false,false},"r",new boolean[]{false,false}),b,model("p",new boolean[]{false,false},"q",new boolean[]{false,false},"r",new boolean[]{false,false}));Result r=ContextSignedUnaryModel.run(x,fs,ms,ContextSignedUnaryModelMatrix.policy());require(r.output!=null,r.reason);Map<Cut,ContextSignedUnaryBranchModel.Extension> es=new LinkedHashMap<>();for(Cut c:ms.keySet())es.put(c,new ContextSignedUnaryBranchModel.Extension(Collections.emptyMap(),Collections.emptyMap()));ContextSignedUnaryBranchModel.Result end=ContextSignedUnaryBranchModel.run(r.output,branch,es,ContextSignedUnaryBranchMatrix.policy());require(end.output!=null,end.reason);require(end.output.ledger.extensions.size()==3,"independent opposite A/B models retained");}
  a=bind(false,"!p(1);!q(2);");b=bind(false,"!~r(1);");for(boolean reverse:new boolean[]{false,true}){ContextSignedWitnessNativeBranch.Receipt no=branch(x,reverse?Arrays.asList(b,a):Arrays.asList(a,b),true);ContextSignedWitnessNativeBranchAudit.check(no,x,no.foreign,no.policy,WORK,64);require(ContextSignedBranchInspection.oppositions(no).stream().anyMatch(o->o.sources.size()==4),"cross-variable different named values cause actual sourced refutation in either order");}
  System.out.println("MULTIVARIABLE_TOPOLOGY independentOrders=2 opposingPrivateModels=true crossVariableRefutationOrders=2");
 }
}
